"use client";

import { forwardRef } from "react";
import { dotPatternDefaults, type DotPatternSpecProps } from "../generated/dot-pattern.types";
import { PatternShell, type PatternDivProps } from "../utils/pattern";

export interface DotPatternProps extends DotPatternSpecProps, Omit<PatternDivProps, keyof DotPatternSpecProps> {}

/** A field of dots that fills its parent. Decoration only: hidden from assistive technology, ignores the pointer. */
export const DotPattern = forwardRef<HTMLDivElement, DotPatternProps>(function DotPattern(
  {
    size = dotPatternDefaults.size,
    gap = dotPatternDefaults.gap,
    color = dotPatternDefaults.color,
    fade = dotPatternDefaults.fade,
    animated = dotPatternDefaults.animated,
    isStill = dotPatternDefaults.isStill,
    duration = dotPatternDefaults.duration,
    ...rest
  },
  ref,
) {
  const tile = size + gap;
  const r = size / 2;
  return (
    <PatternShell
      {...rest}
      ref={ref}
      color={color}
      fade={fade}
      animated={animated}
      isStill={isStill}
      duration={duration}
      period={tile}
      travel={[tile, tile]}
      fill={{
        backgroundImage: `radial-gradient(circle at center, var(--rdm-pc) ${r}px, transparent ${r + 0.5}px)`,
        backgroundSize: `${tile}px ${tile}px`,
      }}
    />
  );
});

// Generated by rdloom codegen from specs/dot-pattern.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

/** A field of evenly spaced dots that fills its parent, with an optional edge fade and a slow drift. */
export interface DotPatternSpecProps {
  /**
   * Dot diameter in pixels.
   * @default 2
   */
  size?: number;
  /**
   * Space between dots in pixels.
   * @default 20
   */
  gap?: number;
  /**
   * Colour of the pattern: any CSS colour or a token such as var(--rd-color-border-default).
   * @default "var(--rd-color-border-default)"
   */
  color?: string;
  /**
   * Fades the pattern out toward its edges.
   * @default true
   */
  fade?: boolean;
  /**
   * Drifts the pattern slowly, one tile per cycle. Off by default.
   * @default false
   */
  animated?: boolean;
  /**
   * Stops the drift. Moving content should be stoppable.
   * @default false
   */
  isStill?: boolean;
  /**
   * Seconds one drift cycle takes.
   * @default 10
   */
  duration?: number;
}

export const dotPatternDefaults = {
  size: 2,
  gap: 20,
  color: "var(--rd-color-border-default)",
  fade: true,
  animated: false,
  isStill: false,
  duration: 10,
} as const;

export const dotPatternMeta = {
  "name": "DotPattern",
  "version": "0.1.0",
  "status": "experimental",
  "role": "presentation"
} as const;
